'use strict';

// Local interaction prototype. These fixtures are illustrative, never live prices.
const instruments = [
  {symbol:'EUR/USD', name:'Euro / US Dollar', category:'Forex', mark:'€', bid:1.08420, ask:1.08432, decimals:5, change:'+0.24%', qty:1000, stop:1.08132, step:1, min:1},
  {symbol:'GBP/USD', name:'British Pound / US Dollar', category:'Forex', mark:'£', bid:1.29144, ask:1.29160, decimals:5, change:'+0.18%', qty:1000, stop:1.28860, step:1, min:1},
  {symbol:'USD/JPY', name:'US Dollar / Japanese Yen', category:'Forex', mark:'¥', bid:151.235, ask:151.251, decimals:3, change:'−0.12%', qty:1000, stop:150.951, step:1, min:1},
  {symbol:'AAPL', name:'Apple Inc.', category:'US equity', mark:'A', bid:221.40, ask:221.44, decimals:2, change:'+0.81%', qty:1, stop:216.44, step:1, min:1}
];
const state={symbol:0,side:'buy',page:'overview',period:'1M',timeframe:'1H',advanced:false,paused:false,strategyPaused:[false,true],modes:['approval','approval'],orders:[],events:[{title:'Practice workspace is ready',detail:'Illustrative account initialized · $10,000 starting balance',time:'Preview'},{title:'Trend breakout v0.1 added',detail:'Research example · approval required · no performance claim',time:'Preview'}],risk:{trade:50,daily:200},sequence:1};
const main=document.querySelector('main');
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2}).format(n);
const number=n=>new Intl.NumberFormat('en-US',{maximumFractionDigits:2}).format(n);
const price=(n,i=instruments[state.symbol])=>n.toFixed(i.decimals);
const titles={overview:'Overview',trade:'Trading workspace',strategies:'Strategies',activity:'Activity',risk:'Risk controls',connections:'Connections & security'};
let toastTimer;
let pendingOrder=null;
try {if(localStorage.getItem('axiom:theme:v1')==='light')document.documentElement.dataset.theme='light';} catch {/* Theme storage is optional. */}
function syncTheme(){const light=document.documentElement.dataset.theme==='light';const b=document.querySelector('#theme-toggle');b.textContent=light?'☾':'☀';b.setAttribute('aria-label',light?'Switch to dark theme':'Switch to light theme');}
syncTheme();
document.querySelector('#theme-toggle').addEventListener('click',()=>{const t=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=t;try{localStorage.setItem('axiom:theme:v1',t);}catch{}syncTheme();});
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4200);}
function heading(eyebrow,title,subtitle,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="muted">${subtitle}</p></div><div class="heading-actions">${actions}</div></div>`;}
function addEvent(title,detail){state.events.unshift({title,detail,time:new Date().toISOString().slice(11,16)+' UTC'});document.querySelector('#activity-count').textContent=state.events.length;}
function eventList(limit){return state.events.slice(0,limit).map(e=>`<div class="activity-item"><span class="event-icon" aria-hidden="true">✓</span><div>${e.title}<small>${e.detail}</small></div><time>${e.time}</time></div>`).join('');}
function stats(){return `<div class="stats"><div class="stat"><div class="stat-label">Illustrative equity <span>↗</span></div><div class="stat-value">$10,428<small>.50</small></div><div class="stat-sub"><span class="up">↗ $428.50</span> from sample starting balance</div></div><div class="stat"><div class="stat-label">Sample unrealized P&L <span>⌁</span></div><div class="stat-value up">+$128<small>.50</small></div><div class="stat-sub">Across 2 illustrative positions</div></div><div class="stat"><div class="stat-label">Illustrative available funds <span>◫</span></div><div class="stat-value">$8,214<small>.20</small></div><div class="stat-sub">Example margin reserved: $2,214.30</div></div><div class="stat"><div class="stat-label">Automation <span>◇</span></div><div class="stat-value">${state.paused?'Paused':'Review'}<small> / paper</small></div><div class="stat-sub">${state.paused?'New paper orders are stopped':'Approval required by default'}</div></div></div>`;}
function lineChart(period){const count=64;const variation={'1W':0,'1M':.8,'3M':1.6}[period]||0;const points=Array.from({length:count},(_,i)=>[18+i*9.2,164-i*1.75+Math.sin(i*.73+variation)*11+Math.cos(i*.27)*9]);const path=points.map((p,i)=>(i?'L':'M')+p.join(',')).join(' ');return `<svg class="chart" viewBox="0 0 670 210" role="img" aria-label="Illustrative equity curve for selected ${period} period. Sample data, not trading results."><defs><linearGradient id="area" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#b7ef83" stop-opacity=".15"/><stop offset="100%" stop-color="#b7ef83" stop-opacity="0"/></linearGradient></defs>${[40,90,140,190].map((y,i)=>`<line class="gridline" x1="15" x2="608" y1="${y}" y2="${y}"/><text x="620" y="${y+3}">${['10,500','10,300','10,100','9,900'][i]}</text>`).join('')}<path d="${path} L598,195 L18,195Z" fill="url(#area)"/><path d="${path}" fill="none" stroke="var(--green)" stroke-width="2" stroke-linejoin="round"/><circle cx="${points.at(-1)[0]}" cy="${points.at(-1)[1]}" r="3" fill="var(--green)"/></svg>`;}
function positions(){return `<div class="table-wrap"><table><thead><tr><th>INSTRUMENT</th><th>SIDE</th><th>QUANTITY</th><th>ENTRY</th><th>SAMPLE P&L</th><th>ENVIRONMENT</th></tr></thead><tbody><tr><td><div class="instrument-cell"><span class="symbol-icon">€</span><div>EUR/USD<small>Forex · illustrative position</small></div></div></td><td><span class="up">Buy</span></td><td>5,000 units</td><td>1.08020</td><td class="up">+$20.60</td><td><span class="pill">Sample</span></td></tr><tr><td><div class="instrument-cell"><span class="symbol-icon">A</span><div>AAPL<small>US equity · illustrative position</small></div></div></td><td><span class="up">Buy</span></td><td>10 shares</td><td>210.61</td><td class="up">+$107.90</td><td><span class="pill">Sample</span></td></tr>${state.orders.map(o=>`<tr><td>${o.symbol}<small class="muted"> · preview fill</small></td><td class="${o.side==='buy'?'up':'down'}">${o.side==='buy'?'Buy':'Sell'}</td><td>${number(o.qty)} ${o.category==='Forex'?'units':'shares'}</td><td>${o.entry.toFixed(o.decimals)}</td><td>—</td><td><span class="pill">Simulated</span></td></tr>`).join('')}</tbody></table></div>`;}
function overview(){return heading('YOUR MARKETS. YOUR CONTROL.','A clearer view of your trading.','Your account, strategies, and next decisions in one place.',`<button class="btn secondary" data-action="toggle-view">${state.advanced?'Simple overview':'Advanced view'} <span>⇄</span></button><a class="btn primary" href="#trade">Open workspace <span class="arrow">↗</span></a>`)+stats()+`<div class="main-grid"><section class="panel"><div class="panel-head"><div><h2>Account performance</h2><p class="muted">An illustration of the performance view</p></div><div class="segmented" aria-label="Chart period">${['1W','1M','3M'].map(p=>`<button data-period="${p}" aria-pressed="${p===state.period}" class="${p===state.period?'selected':''}">${p}</button>`).join('')}</div></div><div class="chart-metric">$10,428.50 <small>↗ 4.29% sample change</small></div>${lineChart(state.period)}<div class="chart-footer"><span>START OF SAMPLE PERIOD</span><span>ILLUSTRATIVE DATA ONLY</span><span>END OF SAMPLE PERIOD</span></div></section><section class="panel"><div class="panel-head"><h2>Risk at a glance</h2><span class="pill green">Example</span></div><div class="risk-top"><div class="muted">Sample daily loss used</div><div class="risk-big">12.5<small>% of limit</small></div><div class="progress"><span style="width:12.5%"></span></div><div class="risk-row"><span>Illustrative loss</span><strong>$25 / $200</strong></div><div class="risk-row"><span>New preview order limit</span><strong>${money(state.risk.trade)}</strong></div><div class="risk-row"><span>Broker risk checks</span><strong>Not connected</strong></div></div><div class="panel-foot"><span>Stay aware of your exposure</span><a class="inline-link" href="#risk">View controls ↗</a></div></section></div>${state.advanced?`<div class="notice"><strong>Advanced detail</strong> · Example gross exposure: $7,635 · Example USD concentration: 62% · No broker reconciliation available in this prototype.</div>`:''}<section class="panel" style="margin-bottom:22px"><div class="panel-head"><div><h2>Positions</h2><p class="muted">2 illustrative positions${state.orders.length?` + ${state.orders.length} preview fills`:''}</p></div><a class="inline-link" href="#trade">Manage workspace ↗</a></div>${positions()}</section><div class="bottom-grid"><section class="panel"><div class="panel-head"><h2>Your strategies</h2><a class="inline-link" href="#strategies">View all ↗</a></div><div class="strategy-row"><span class="strategy-icon">⌁</span><div><div class="strategy-title">Trend breakout <span class="muted">v0.1</span></div><div class="muted">EUR/USD · Research example · No validated results</div></div><span class="pill ${state.strategyPaused[0]?'':'green'}">${state.strategyPaused[0]?'Paused':'Approval required'}</span></div><div class="strategy-row"><span class="strategy-icon">◇</span><div><div class="strategy-title">Session momentum <span class="muted">v0.1</span></div><div class="muted">GBP/USD · Research example</div></div><span class="pill">${state.strategyPaused[1]?'Paused':'Approval required'}</span></div></section><section class="panel"><div class="panel-head"><h2>Recent activity</h2><a class="inline-link" href="#activity">View history ↗</a></div>${eventList(2)}</section></div>`;}
function candles(){const offset=state.symbol*.8+['15M','1H','4H','1D'].indexOf(state.timeframe)*.35;return `<svg class="chart" viewBox="0 0 670 330" role="img" aria-label="Illustrative candlestick chart for ${instruments[state.symbol].symbol}, ${state.timeframe}. This is generated sample data.">${[40,100,160,220,280].map(y=>`<line class="gridline" x1="15" x2="600" y1="${y}" y2="${y}"/>`).join('')}${Array.from({length:62},(_,i)=>{const open=245-i*2.5+Math.sin(i*.52+offset)*22;const close=open+Math.cos(i*.89+offset)*17;const up=close<open;return `<line x1="${20+i*9}" x2="${20+i*9}" y1="${Math.min(open,close)-9}" y2="${Math.max(open,close)+8}" stroke="${up?'var(--positive)':'var(--negative)'}"/><rect x="${17+i*9}" y="${Math.min(open,close)}" width="6" height="${Math.max(2,Math.abs(open-close))}" fill="${up?'var(--positive)':'var(--negative)'}"/>`;}).join('')}<text x="15" y="320">08:00</text><text x="180" y="320">10:00</text><text x="360" y="320">12:00</text><text x="545" y="320">14:00</text><text x="610" y="75">SAMPLE</text></svg>`;}
function trade(){const i=instruments[state.symbol];return heading('TRADING WORKSPACE','Make your next move.','Explore an instrument, review your risk, and try a paper order.',`<span class="pill amber">Generated sample chart</span>`)+`<div class="trade-grid"><section class="panel watch-panel"><div class="panel-head"><h2>Watchlist</h2><span class="muted">4</span></div><div>${instruments.map((x,n)=>`<button class="watch-item ${n===state.symbol?'active':''}" data-symbol="${n}" aria-pressed="${n===state.symbol}"><div>${x.symbol}<small>${x.category}</small></div><div>${price(x.bid,x)}<small class="${x.change.startsWith('−')?'down':'up'}">${x.change}</small></div></button>`).join('')}</div></section><section class="panel trade-chart"><div class="panel-head"><div><h2>${i.symbol}</h2><p class="muted">${i.name} · ${i.category}</p></div><div class="segmented" aria-label="Chart timeframe">${['15M','1H','4H','1D'].map(t=>`<button data-timeframe="${t}" class="${t===state.timeframe?'selected':''}" aria-pressed="${t===state.timeframe}">${t}</button>`).join('')}</div></div><div class="quote-line"><div><small>SAMPLE BID</small><strong>${price(i.bid)}</strong></div><div><small>SAMPLE ASK</small><strong class="up">${price(i.ask)}</strong></div></div>${candles()}<div class="panel-foot"><span>Illustrative bars · no market feed</span><span>${state.timeframe}</span></div></section><section class="panel ticket-panel"><div class="panel-head"><h2>Paper order</h2><span class="pill">USD</span></div><form class="order-form" id="ticket"><div class="buy-sell"><button type="button" data-side="buy" aria-pressed="${state.side==='buy'}" class="${state.side==='buy'?'selected':''}">Buy / Long</button><button type="button" data-side="sell" aria-pressed="${state.side==='sell'}" class="${state.side==='sell'?'selected':''}">Sell / Short</button></div><label class="field">Order type<select name="type"><option>Market · simulated</option></select></label><label class="field">Quantity (${i.category==='Forex'?'base units':'shares'})<input name="quantity" type="number" min="${i.min}" step="${i.step}" value="${i.qty}" required inputmode="decimal"></label><label class="field">Illustrative stop price<input name="stop" type="number" min="${(1 / 10**i.decimals).toFixed(i.decimals)}" step="${(1 / 10**i.decimals).toFixed(i.decimals)}" value="${price(state.side==='buy'?i.stop:i.bid+(i.ask-i.stop))}" required inputmode="decimal"></label><div><div class="order-detail"><span>Sample fill price</span><strong>${price(state.side==='buy'?i.ask:i.bid)}</strong></div><div class="order-detail"><span>Estimated stop loss*</span><strong id="loss-estimate">—</strong></div><div class="order-detail"><span>Preview order limit</span><strong>${money(state.risk.trade)}</strong></div></div><p class="muted" style="font-size:9px">*Fixture calculation before fees, gaps, and slippage. Stops do not guarantee a fill price.</p><div class="form-error" id="order-error" role="alert"></div><button class="btn primary full" ${state.paused?'disabled':''}>${state.paused?'New orders paused':'Review paper order →'}</button></form></section></div><section class="panel trade-bottom"><div class="panel-head"><h2>Positions & preview fills</h2><span class="pill">Illustrative</span></div>${positions()}</section>`;}
function strategies(){return heading('STRATEGY LIBRARY','Understand the rules. Stay in control.','Research examples for designing the workflow. No strategy has been selected or validated.')+`<div class="cards-2">${['Trend breakout','Session momentum'].map((name,n)=>`<section class="panel content-card"><div class="card-top"><span class="strategy-icon">${n?'◇':'⌁'}</span><span class="pill ${state.strategyPaused[n]?'':'green'}">${state.strategyPaused[n]?'Paused':'Paper preview'}</span></div><h2>${name} <span class="muted">v0.1</span></h2><p class="muted">${n?'A placeholder for a strategy based on session behavior.':'A placeholder for a strategy based on a defined price range.'} Rules and research evidence will be reviewed before implementation.</p><div class="detail-list"><div><span>Instrument</span><strong>${n?'GBP/USD':'EUR/USD'}</strong></div><div><span>Validated performance</span><strong>Not available</strong></div><div><span>Strategy execution engine</span><strong>Not implemented</strong></div></div><label class="field">Execution preference<select data-mode="${n}"><option value="approval" ${state.modes[n]==='approval'?'selected':''}>Ask me to approve each order</option><option value="automatic" ${state.modes[n]==='automatic'?'selected':''}>Automatic · paper preview only</option></select></label><button class="btn secondary full" data-strategy="${n}">${state.strategyPaused[n]?'Resume preview strategy':'Pause preview strategy'}</button></section>`).join('')}</div><div class="notice">Changing these controls records a design interaction. Automatic signal generation and strategy trading are not running in this prototype.</div>`;}
function activity(){return heading('ORDER & DECISION HISTORY','Every decision, in view.','Follow sample activity and the actions you take in this preview.')+`<section class="panel"><div class="panel-head"><h2>Workspace activity</h2><span class="pill">This tab only</span></div>${eventList(100)}</section><p class="page-note">Preview actions reset when the page reloads. This history is not a production audit log.</p>`;}
function risk(){return heading('RISK CONTROLS','Set boundaries before the trade.','Try the control layout. Values apply to new manual preview orders in this browser tab.')+`<div class="settings-grid"><section class="panel content-card"><h2>Preview order limits</h2><p class="muted">Illustrative USD account. Choose values for exploring the design.</p><form id="risk-form"><label class="field">Maximum estimated stop loss per order (USD)<input type="number" name="trade" value="${state.risk.trade}" min="1" max="10000" step="1" required></label><label class="field">Daily loss limit (USD) · display preference only<input type="number" name="daily" value="${state.risk.daily}" min="1" max="10000" step="1" required></label><p class="muted">Daily loss accounting and broker margin checks will be implemented in the backend. This preview does not enforce them.</p><div class="form-error" id="risk-error" role="alert"></div><button class="btn primary">Save preview limits</button></form></section><section class="panel content-card"><h2>Automation & exposure</h2><div class="setting-row"><div><strong>Stop new preview orders</strong><p>Does not close positions or cancel existing orders.</p></div><button class="switch" role="switch" aria-label="Stop new preview orders" aria-checked="${state.paused}" data-action="pause-orders"></button></div><div class="setting-row"><div><strong>Portfolio exposure checks</strong><p>Currency concentration and concurrent risk reservations.</p></div><span class="pill">Planned</span></div><div class="setting-row"><div><strong>Broker margin checks</strong><p>Requires a qualified broker integration.</p></div><span class="pill">Planned</span></div><div class="notice">Production limits will run on the server and be checked again before every order submission.</div></section></div>`;}
function connections(){return heading('CONNECTIONS & SECURITY','Your accounts. Your permissions.','Broker selection and identity-provider integration are still in research.')+`<div class="settings-grid"><section class="panel content-card"><div class="card-top"><span class="strategy-icon">⊞</span><span class="pill amber">No broker connected</span></div><h2>Find the right connection</h2><p class="muted">The app will show eligible brokers based on residence, supported instruments, and authorized API access.</p><div class="detail-list"><div><span>Development location</span><strong>Nigeria</strong></div><div><span>Broker qualification</span><strong>In research</strong></div><div><span>Credentials collected</span><strong>None</strong></div></div><div class="notice">This preview does not accept broker passwords or API keys. Account connection will use the selected broker's authorized flow.</div></section><section class="panel content-card"><h2>Account protection</h2><div class="setting-row"><div><strong>Multi-factor authentication</strong><p>Available after the identity service is integrated.</p></div><span class="pill">Planned</span></div><div class="setting-row"><div><strong>Active sessions & revocation</strong><p>Review signed-in devices and revoke access.</p></div><span class="pill">Planned</span></div><div class="setting-row"><div><strong>Broker trading permissions</strong><p>Explicit consent for each connected account.</p></div><span class="pill">Planned</span></div><p class="page-note">These are design requirements, not implemented security controls.</p></section></div>`;}
function render(){const hash=location.hash.slice(1);state.page=hash==='research'?'research':Object.hasOwn(titles,hash)?hash:'overview';document.querySelector('#breadcrumb').textContent=state.page==='research'?'Research lab':titles[state.page];document.querySelectorAll('[data-page]').forEach(a=>{const current=a.dataset.page===state.page;a.classList.toggle('active',current);if(current)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});if(state.page==='research'){main.innerHTML='<div id="research-root"></div>';window.dispatchEvent(new Event('research:mount'));return;}main.innerHTML=({overview,trade,strategies,activity,risk,connections})[state.page]();if(state.page==='trade')updateEstimate();}
function calculateOrder(){const form=document.querySelector('#ticket');const i=instruments[state.symbol];const qty=Number(form.elements.quantity.value);const stop=Number(form.elements.stop.value);const entry=state.side==='buy'?i.ask:i.bid;let error='';if(!Number.isFinite(qty)||qty<i.min||!Number.isInteger(qty/i.step))error='Enter a valid whole-unit quantity.';else if(!Number.isFinite(stop)||stop<=0)error='Enter a valid positive stop price.';else if(state.side==='buy'?stop>=entry:stop<=entry)error=state.side==='buy'?'Buy stop price must be below the sample entry.':'Sell stop price must be above the sample entry.';const loss=Math.abs(entry-stop)*qty/(i.symbol==='USD/JPY'?i.bid:1);if(!error&&loss>state.risk.trade)error=`Estimated stop loss exceeds your ${money(state.risk.trade)} preview limit.`;return {...i,qty,stop,entry,side:state.side,loss,error};}
function updateEstimate(){const o=calculateOrder();document.querySelector('#loss-estimate').textContent=Number.isFinite(o.loss)?money(o.loss):'—';}
main.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.period){state.period=b.dataset.period;render();}else if(b.dataset.timeframe){state.timeframe=b.dataset.timeframe;render();}else if(b.dataset.symbol!==undefined){state.symbol=Number(b.dataset.symbol);render();}else if(b.dataset.side){state.side=b.dataset.side;render();}else if(b.dataset.action==='toggle-view'){state.advanced=!state.advanced;render();}else if(b.dataset.action==='pause-orders'){state.paused=!state.paused;addEvent(state.paused?'New preview orders stopped':'New preview orders resumed','Existing illustrative positions unchanged');render();toast(state.paused?'New preview orders are paused.':'New preview orders are available.');}else if(b.dataset.strategy!==undefined){const n=Number(b.dataset.strategy);state.strategyPaused[n]=!state.strategyPaused[n];addEvent(`${n?'Session momentum':'Trend breakout'} ${state.strategyPaused[n]?'paused':'resumed'}`,'Preview preference only · strategy engine is not running');render();toast('Preview strategy preference updated.');}});
main.addEventListener('change',e=>{if(e.target.dataset.mode!==undefined){const n=Number(e.target.dataset.mode);state.modes[n]=e.target.value;addEvent('Execution preference changed',`${n?'Session momentum':'Trend breakout'} · ${e.target.value==='automatic'?'automatic paper preview':'approval required'}`);toast('Preference saved for this tab. No strategy engine is running.');}});
main.addEventListener('input',e=>{if(e.target.closest('#ticket'))updateEstimate();});
main.addEventListener('submit',e=>{e.preventDefault();if(e.target.id==='ticket'){const o=calculateOrder();const error=document.querySelector('#order-error');error.textContent=o.error;if(state.paused){error.textContent='New preview orders are paused.';return;}if(o.error)return;pendingOrder=o;document.querySelector('#order-review').innerHTML=`<div class="detail-list"><div><span>Instrument</span><strong>${o.symbol}</strong></div><div><span>Direction</span><strong>${o.side==='buy'?'Buy / Long':'Sell / Short'}</strong></div><div><span>Quantity</span><strong>${number(o.qty)} ${o.category==='Forex'?'units':'shares'}</strong></div><div><span>Sample fill price</span><strong>${o.entry.toFixed(o.decimals)}</strong></div><div><span>Illustrative stop</span><strong>${o.stop.toFixed(o.decimals)}</strong></div><div><span>Estimated stop loss before costs</span><strong>${money(o.loss)}</strong></div></div>`;document.querySelector('#order-dialog').showModal();}else if(e.target.id==='risk-form'){const trade=Number(e.target.elements.trade.value),daily=Number(e.target.elements.daily.value);const error=document.querySelector('#risk-error');if(!Number.isInteger(trade)||!Number.isInteger(daily)||trade<1||daily<1||trade>10000||daily>10000){error.textContent='Enter whole-dollar limits between $1 and $10,000.';return;}if(trade>daily){error.textContent='Per-order limit must not exceed the daily display limit.';return;}state.risk={trade,daily};addEvent('Preview limits updated',`Per-order stop-loss estimate: ${money(trade)} · daily display preference: ${money(daily)}`);error.textContent='';toast('Preview limits saved for this tab.');}});
document.querySelector('#order-dialog').addEventListener('close',e=>{if(e.target.returnValue==='confirm'&&pendingOrder&&!state.paused){const o=pendingOrder;state.orders.push({...o,id:state.sequence++});addEvent(`${o.side==='buy'?'Buy':'Sell'} ${o.symbol} · simulated fill`,`${number(o.qty)} ${o.category==='Forex'?'units':'shares'} at ${o.entry.toFixed(o.decimals)} · preview only`);render();toast('Paper order simulated. View the fill in positions and activity.');}pendingOrder=null;});
window.addEventListener('hashchange',()=>{if(location.hash==='#main'){main.focus();return;}render();main.focus({preventScroll:true});window.scrollTo(0,0);});
render();
